import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Configuration (gflags)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1790847150000}'),l={name:"guide/configuration.md"};function n(o,e,d,r,h,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="configuration-gflags" tabindex="-1">Configuration (gflags) <a class="header-anchor" href="#configuration-gflags" aria-label="Permalink to &quot;Configuration (gflags)&quot;">​</a></h1><p>NeoFlux uses <a href="https://github.com/gflags/gflags" target="_blank" rel="noreferrer">gflags</a> for runtime configuration and <a href="https://github.com/google/glog" target="_blank" rel="noreferrer">glog</a> for logging. Every flag below is optional and passed on the command line:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hello_neoflux.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_fps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr</span></span></code></pre></div><h2 id="full-flag-reference" tabindex="-1">Full flag reference <a class="header-anchor" href="#full-flag-reference" aria-label="Permalink to &quot;Full flag reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Type</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--render_backend</code></td><td><code>string</code></td><td><code>&quot;vulkan&quot;</code></td><td>Selects the tgfx render backend. Accepted values: <code>vulkan</code>, <code>gl</code>, <code>cpu</code>.</td></tr><tr><td><code>--target_fps</code></td><td><code>int32</code></td><td><code>60</code></td><td>Target frames-per-second for the application event loop.</td></tr><tr><td><code>--render_queue_capacity</code></td><td><code>uint64</code></td><td><code>2048</code></td><td>Capacity of the SPSC render-command ring queue. Rounded up to a power of two; one slot is reserved, so usable commands = <code>capacity - 1</code>.</td></tr><tr><td><code>--verbose_logging</code></td><td><code>bool</code></td><td><code>false</code></td><td>Enables <code>VLOG(1)</code> output and mirrors INFO logs to stderr.</td></tr><tr><td><code>--logtostderr</code></td><td><code>bool</code></td><td><code>false</code></td><td>When set, writes all logs to stderr instead of files.</td></tr><tr><td><code>--log_dir</code></td><td><code>string</code></td><td><code>&quot;./logs&quot;</code></td><td>Directory for <code>.log</code> files (created automatically). Only used when <code>--logtostderr</code> is off.</td></tr></tbody></table><h3 id="render-backend" tabindex="-1"><code>--render_backend</code> <a class="header-anchor" href="#render-backend" aria-label="Permalink to &quot;`--render_backend`&quot;">​</a></h3><p>Defined in <code>src/render/render_layer.cpp</code>. Three values are accepted:</p><table tabindex="0"><thead><tr><th>Value</th><th>Behavior</th></tr></thead><tbody><tr><td><code>vulkan</code> (default)</td><td>Reserved. Not yet implemented — logs a warning and falls back to OpenGL.</td></tr><tr><td><code>gl</code></td><td>OpenGL backend (the currently working desktop path, via GLFW/WGL).</td></tr><tr><td><code>cpu</code></td><td>Software rasterizer. Not yet implemented — logs a warning and falls back to OpenGL.</td></tr></tbody></table><p>Any unrecognised value also logs a warning and uses the OpenGL path.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Even though the default string is <code>&quot;vulkan&quot;</code>, on today&#39;s desktop builds every option effectively renders through GL. Pass <code>--render_backend=gl</code> to make the intent explicit.</p></div><h3 id="target-fps" tabindex="-1"><code>--target_fps</code> <a class="header-anchor" href="#target-fps" aria-label="Permalink to &quot;`--target_fps`&quot;">​</a></h3><p>Sets <code>EventLoop::SetTargetFps()</code>. The loop sleeps between frames to respect the cap; input events and <code>MarkFrameDirty()</code> wake it early. Default <code>60</code>.</p><h3 id="render-queue-capacity" tabindex="-1"><code>--render_queue_capacity</code> <a class="header-anchor" href="#render-queue-capacity" aria-label="Permalink to &quot;`--render_queue_capacity`&quot;">​</a></h3><p>Configures the <code>SpscRingQueue&lt;RenderCommand&gt;</code> constructed by <code>RenderLayer</code>. The value is rounded up to the next power of two internally. Because one slot is reserved to distinguish full from empty, a requested <code>2048</code> holds at most <code>2047</code> in-flight commands. If the producer catches up to the consumer, excess commands for that frame are dropped (rate-limited warning).</p><div class="warning custom-block"><p class="custom-block-title">Raise this only if you see &quot;render command queue full&quot; warnings</p><p>A larger queue costs memory and can add present latency. The default <code>2048</code> is plenty for typical widget trees.</p></div><h3 id="verbose-logging" tabindex="-1"><code>--verbose_logging</code> <a class="header-anchor" href="#verbose-logging" aria-label="Permalink to &quot;`--verbose_logging`&quot;">​</a></h3><p>A convenience bool. When set, NeoFlux turns on <code>VLOG(1)</code> (<code>FLAGS_v = 1</code>) and mirrors INFO-level logs to stderr. This is the switch that makes the per-frame layout dump (<code>VLOG(1) &lt;&lt; widgetname [x y w h]</code>) appear.</p><h3 id="logtostderr" tabindex="-1"><code>--logtostderr</code> <a class="header-anchor" href="#logtostderr" aria-label="Permalink to &quot;`--logtostderr`&quot;">​</a></h3><p>This is a glog built-in flag. When glog is built without gflags integration, NeoFlux pre-scans <code>argv</code> for <code>--logtostderr</code> / <code>--nologtostderr</code> (and the <code>-</code> short forms) before gflags parses the rest. By default it is off and logs go to files.</p><h3 id="log-dir" tabindex="-1"><code>--log_dir</code> <a class="header-anchor" href="#log-dir" aria-label="Permalink to &quot;`--log_dir`&quot;">​</a></h3><p>Also a glog built-in flag, handled by the same argv pre-scan. Accepts both <code>--log_dir=PATH</code> and <code>--log_dir PATH</code>. When logging to files, it defaults to <code>./logs</code>, creates the directory if needed, and appends the <code>.log</code> extension. If the directory cannot be created, logging silently falls back to stderr.</p><h2 id="logging-in-code" tabindex="-1">Logging in code <a class="header-anchor" href="#logging-in-code" aria-label="Permalink to &quot;Logging in code&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;glog/logging.h&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(INFO) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Application started&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(WARNING) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Font not found, using default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ERROR) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Rendering failed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VLOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Detailed per-frame debug info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // shown with --verbose_logging</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Recommended development invocation</p><p>Because examples are built as GUI-subsystem binaries with no console, run with:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hello_neoflux.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div></div><h2 id="full-example" tabindex="-1">Full example <a class="header-anchor" href="#full-example" aria-label="Permalink to &quot;Full example&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hello_neoflux.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_fps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">144</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_queue_capacity</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div><p>This targets 144 FPS, forces the GL backend, enlarges the command queue to 4096, and streams verbose logs to the terminal.</p>',27)])])}const k=s(l,[["render",n]]);export{g as __pageData,k as default};
